  data -> search;
  search -> fold1;
  search -> fold2;
  search -> fold3;

  subgraph cluster_cv {
    label="3-fold CV (repeat for each candidate setting)";
    style="rounded,filled";
    color="#D9E8FB";
    fold1 [label="Fold 1 held out\nTrain on folds 2–3\nValidate on fold 1", fillcolor="#F6B6B6"];
    fold2 [label="Fold 2 held out\nTrain on folds 1 & 3\nValidate on fold 2", fillcolor="#F6B6B6"];
    fold3 [label="Fold 3 held out\nTrain on folds 1–2\nValidate on fold 3", fillcolor="#F6B6B6"];
  }

  fold1 -> score;
  fold2 -> score;
  fold3 -> score;
  score -> best;
  best -> refit;
}
